<?php $cell=fn(...$args)=>'<div class="schedule-field">'.$this->field(...$args).'</div>'; ?>
<header class="schedule-heading"><span class="eyebrow">پیگیری گفت‌وگوها</span><h1><?= $admin?'مدیریت رزروها':'درخواست‌ها و جلسات من' ?></h1></header>
<?php if(!$admin): ?><nav class="saved-tabs" aria-label="نوع درخواست"><?php foreach(['outgoing'=>'درخواست‌های ارسالی']+(!empty($isMentor)?['incoming'=>'درخواست‌های دریافتی']:[]) as $key=>$label): ?><a <?= $direction===$key?'aria-current="page"':'' ?> href="<?= $this->h($this->url('/sessions?direction='.$key.'&period='.$period)) ?>"><?= $label ?></a><?php endforeach; ?></nav><nav class="session-filters" aria-label="تاریخچهٔ جلسات"><?php foreach(['all'=>'همه','future'=>'پیش رو','past'=>'گذشته','cancelled'=>'لغو، رد و انقضا'] as $key=>$label): ?><a <?= $period===$key?'aria-current="page"':'' ?> href="<?= $this->h($this->url('/sessions?direction='.$direction.'&period='.$key)) ?>"><?= $label ?></a><?php endforeach; ?></nav><?php endif; ?>
<?php if($admin): ?><details class="card schedule-card"><summary>ثبت درخواست داخلی</summary><p>رزرو عمومی بسته است؛ زیرساخت تماس، تصویر و چت جداگانه آماده می‌شود.</p><?= $this->start('/bookings/internal') ?><div class="schedule-fields"><?= $cell('user_id','شناسهٔ کاربر') ?><?= $cell('mentor_id','شناسهٔ مرشد') ?></div><?= $cell('subject','موضوع مشاوره') ?><?= $cell('experience_id','شناسهٔ تجربهٔ مرتبط (اختیاری)','text','',false) ?><?= $cell('starts_local','روز و ساعت شروع به وقت تهران','datetime-local') ?><input type="hidden" name="idempotency_key" value="<?= $this->val('idempotency_key',bin2hex(random_bytes(16))) ?>"><label for="request-method">روش درخواستی پس از آماده‌شدن زیرساخت</label><select id="request-method" name="requested_method"><option value="audio">صوتی</option><option value="video">تصویری</option><option value="chat">چت</option></select><label for="booking-problem">شرح نیاز</label><textarea id="booking-problem" name="problem" required maxlength="6000"><?= $this->val('problem') ?></textarea><button>ثبت درخواست در انتظار تأیید</button></form></details><?php endif; ?>
<div class="booking-list"><?php foreach($rows as $b): ?><article class="card booking-list-item"><div class="booking-list-top"><span class="booking-badge state-<?= $this->h($b['state']) ?>"><?= $this->status($b['state']) ?></span><span class="small muted"><?= !$admin&&$b['mentor_id']===$this->actor['user_id']?'دریافتی':'ارسالی' ?></span></div><h2><?= $this->h($b['subject']??'درخواست مشاوره') ?></h2><p><?= !$admin&&$b['mentor_id']===$this->actor['user_id']?'درخواست‌دهنده: '.$this->h($b['user_name']):'مرشد: '.$this->h($b['mentor_name']) ?></p><div class="booking-time"><?= $this->icon('calendar') ?><time data-timestamp="<?= (int)$b['starts_at'] ?>"><?= $this->h(gmdate('Y-m-d H:i',(int)$b['starts_at'])) ?> UTC</time><span>تا</span><time data-timestamp="<?= (int)$b['ends_at'] ?>"><?= $this->h(gmdate('H:i',(int)$b['ends_at'])) ?> UTC</time></div><?php if(!empty($b['experience_title'])): ?><p class="small muted">تجربه: <?= $this->h($b['experience_title']) ?></p><?php endif; ?><a class="secondary" href="<?= $this->h($this->url('/booking?id='.$b['id'])) ?>">مشاهدهٔ جزئیات و پیگیری <?= $this->icon('arrow') ?></a></article><?php endforeach; ?></div><?php if(!$rows): ?><div class="discovery-empty"><?= $this->icon('calendar') ?><h2>درخواستی در این بخش نیست</h2><p>درخواست‌ها و تغییر وضعیت آن‌ها پس از ثبت، اینجا نمایش داده می‌شوند.</p></div><?php endif; ?>
